,"00EF":"Ｋ・랍스터캡,0,0,5,,2,5,2,3,4,64,4,56,4,40,2,,,,,,01D31R 01D21 00183 00DA4,15,0027,7,8000,15,0,2,02,0C,02,0,1-,,,,,희귀한 킹랍스터의 껍데기를 아낌없이 사용한 머리 방어구. 의외로 단단하다.,E8"
,"00F0":"기술의 피어스,0,0,7,,0,0,5,0,0,32,10,31,-25,,,,,,,,훈련전용,1,0000,1,0,10,0,0,00,00,01,0,7-,,,,,이것을 장착하면 기술이 예리해져 명인의 달인을 쓸 수 있지만 체력이 크게 줄어든다."
,"00F1":"힘의 피어스,0,0,7,,5,0,0,0,0,21,25,47,10,56,-25,9,-5,,,,훈련전용,1,0000,1,0,10,0,0,00,00,01,0,7-,,,,,이를 장착하면 힘이 솟아올라， 절대적인 파워를 얻는다… 하지만， 방어가 허술해진다."
,"00F2":"생명의 피어스,0,0,7,,0,0,0,0,5,31,25,56,25,57,-10,46,-10,,,,훈련전용,1,0000,1,0,10,0,0,00,00,01,0,7-,,,,,이것을 장착하면 삶의 활력이 솟아 체력도 방어력도 오르나 마비나 독에 약해진다."
,"00F3":"명인의 피어스,0,0,7,,0,5,0,0,0,9,10,72,10,40,10,6,-10,,,,훈련전용,1,0000,1,0,10,0,0,00,00,01,0,7-,,,,,이것을 장착하면 여러 명인의 기억이 되살아나， 뛰어난 실력의 명인이 될 수 있다."
,"00F4":"장인의 피어스,0,0,7,,1,1,1,0,1,17,10,3,10,67,10,51,-10,,,,훈련전용,1,0000,1,0,11,0,0,00,00,01,0,7-,,,,,실로 장인의 솜씨! 알 운반엔 이것을 착용하는 수밖에 없다! 하지만… 배고픈 게 옥에 티."
,"00F5":"고수의 피어스,0,0,7,,2,2,2,0,2,62,10,38,10,17,-10,67,-10,,,,훈련전용,1,0000,1,0,7,0,0,00,00,01,0,7-,,,,,이것을 장착하면 마구 쏘지만， 비룡에게 습격당하기 쉽고 스태미나 소모도 격심하다."
,"00F6":"강운의 피어스,0,0,7,,3,3,3,0,3,9,10,22,15,50,10,35,-10,,,,훈련전용,1,0000,1,0,3,0,0,00,00,01,0,7-,,,,,이것을 장착하면 운이 좋아져 희귀 아이템을 얻을지도… 하지만 지도를 읽지 못한다."
